insert into interlock (source_equipment_id, target_equipment_id, interlock_type, description) values
  ('30000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000002', '정기점검 동시점검', '정기점검 시 GT 발전기와 AVR을 함께 점검. 개별 고장(발전기측 또는 AVR측 단독) 발생 시에는 분리하여 Red-Tag를 발행할 것.'),
  ('30000000-0000-0000-0000-000000000013', '30000000-0000-0000-0000-000000000001', '작업범위 중복(안전요건)', 'SFC 점검의 SW-307(SFC)은 GT 발전기 점검에서도 개방하는 동일 차단기 — GT 발전기 작업과 함께 하면 이미 개방되어 중복.'),
  ('30000000-0000-0000-0000-000000000013', '30000000-0000-0000-0000-000000000002', '작업범위 중복(안전요건)', 'SFC 점검의 MCCB-Q13(START 여자기)은 GT AVR 점검에서도 개방하는 동일 차단기 — GT AVR 작업과 함께 하면 이미 개방되어 중복.'),
  ('30000000-0000-0000-0000-000000000004', '30000000-0000-0000-0000-000000000005', '정기점검 동시점검', '정기점검("GT 변압기(SUT,AUT) 점검") 시 SUT-1과 AUT-1을 함께 점검. 개별 고장 시에는 분리하여 Red-Tag 발행할 것. AUT-1 단독 작업 시 1차측 공통단(GMCB-06, GT 발전기 소속)의 개방 필요 여부 확인 필요.'),
  ('30000000-0000-0000-0000-000000000006', '30000000-0000-0000-0000-000000000007', '정기점검 동시점검', '정기점검 시 SUT-2와 AUT-2를 함께 점검. 개별 고장 시에는 분리하여 Red-Tag 발행할 것. AUT-2 단독 작업 시 1차측 공통단(GMCB-07, ST 발전기 소속)의 개방 필요 여부 확인 필요.'),
  ('30000000-0000-0000-0000-000000000004', '30000000-0000-0000-0000-000000000006', '작업순서 제약(동시진행 불가)', '도면 주석(403-1-E-SL-432-001): "GTG 변압기 점검 및 STG 변압기 점검 순차적 진행" — 전기적 연동정전은 아니나 두 작업을 동시에 진행할 수 없음.'),
  ('30000000-0000-0000-0000-000000000122', '30000000-0000-0000-0000-000000000004', '작업범위 중복(안전요건)', 'SWGR-3 INCOMING PT 단독 작업 시 GCB-03/DS-301/302/303 개방 필수(PT인출 시 1차측 감전위험). SUT-1 작업과 함께 하면 이미 개방되어 중복.'),
  ('30000000-0000-0000-0000-000000000122', '30000000-0000-0000-0000-000000000005', '작업범위 중복(안전요건)', 'SWGR-3 INCOMING PT는 AUT-1의 2차측 — 함께 점검 권장.'),
  ('30000000-0000-0000-0000-000000000131', '30000000-0000-0000-0000-000000000006', '작업범위 중복(안전요건)', 'SWGR-4 INCOMING PT 단독 작업 시 GCB-04/DS-401/402/403 개방 필수(PT인출 시 1차측 감전위험). SUT-2 작업과 함께 하면 이미 개방되어 중복.'),
  ('30000000-0000-0000-0000-000000000131', '30000000-0000-0000-0000-000000000007', '작업범위 중복(안전요건)', 'SWGR-4 INCOMING PT는 AUT-2의 2차측 — 함께 점검 권장.'),
  ('30000000-0000-0000-0000-000000000120', '30000000-0000-0000-0000-000000000111', '조작주의(정전확산위험)', '⚠️ VCB-201이 투입 상태일 때 VCB-217을 개방하면 #2 SWGR 버스가 전체 정전됨(VCB-201 투입 시 그 후단에서 VCB-217을 통해 #2 SWGR로 급전되는 경로가 생기기 때문). VCB-217 개방 전 VCB-201 상태를 반드시 확인할 것(사용자 확인 2026-08-09).');
